    private sealed record PlayerTurnPreparation(
        string Generation,
        RollbackSnapshot Backup,
        TurnRequest Request,
        ValidatedPendingTurnSnapshotContext SnapshotContext,
        PendingPlayerActionService.Staged? BrowserStaged);

    private async Task ProcessPlayerTurn(
        string action,
        string? extraSystemReminder = null,
        string? waitingTitle = null,
        string? waitingText = null,
        bool playerFacingTurn = true,
        PendingPlayerActionService.Binding? browserAction = null)
    {
        if (browserAction == null)
        {
            // Console ordinary turns retain their original continuous owner.
            await SessionOperationContext.RunParticipatingCurrentSessionAsync(_fs, async () =>
            {
                var preparation = await StagePlayerTurnAsync(action, extraSystemReminder, null);
                if (preparation == null) return;
                PublishAgentConsoleGmWaitingSnapshot(
                    waitingTitle ?? PlayerSafeWaitingTitle, waitingText ?? PlayerSafeWaitingText);
                var outcome = await WaitForTerminalSignalAsync();
                await FinalizePlayerTurnAsync(preparation, action, playerFacingTurn, outcome);
            });
            return;
        }

        MainOperationClose? stagingClose = null;
        bool stagingCloseObserved = false, stagingWasRemote = false;
        var stagedPreparation = await SessionOperationContext.RunParticipatingCurrentSessionAsync(_fs,
            () => StagePlayerTurnAsync(action, extraSystemReminder, browserAction),
            observeOriginalClose: (close, observed, remote) =>
            {
                // Copy actual close facts only. Await-using disposal still follows
                // this callback; the idle boundary starts after the top-level await.
                stagingClose = close;
                stagingCloseObserved = observed;
                stagingWasRemote = remote;
            });
        if (stagedPreparation == null) return;
        var browserStaged = stagedPreparation.BrowserStaged ?? throw BrowserOriginalMainCondition.Invalid();
        PublishAgentConsoleGmWaitingSnapshot(
            waitingTitle ?? PlayerSafeWaitingTitle, waitingText ?? PlayerSafeWaitingText);
#if DEBUG
        await HoldOriginalBrowserIdleCutAsync(browserStaged, stagingClose, stagingCloseObserved, stagingWasRemote);
#endif
        var browserOutcome = await WaitForTerminalSignalWithParticipationAsync(browserStaged);
#if DEBUG
        using var diagnosticWindow = _fs.BrowserDiagnosticWindow(stagedPreparation.Request.RequestId ?? "unbound", browserStaged.Binding.ActionId, browserStaged.Binding.Generation);
        try
        {
#endif
        await SessionOperationContext.RunParticipatingExpectedSessionAsync(_fs, stagedPreparation.Generation, async () =>
        {
            using var original = _fs.BeginBrowserOriginalOperation(browserStaged.Binding, browserStaged);
#if DEBUG
            using var diagnosticOwner = _fs.BrowserDiagnosticIdentity(null, browserStaged.Binding.ActionId,
                browserStaged.Binding.Generation, original.Condition.ActiveIdentity);
            using var diagnosticCaller = _fs.BrowserDiagnosticLogical(null, "browser-terminal-finalization");
            _fs.BrowserDiagnosticMark("processing-owner");
#endif
            var manifest = await LoadPendingTurnSnapshotManifestAsync();
            var context = await LoadValidatedPendingTurnSnapshotContextAsync(manifest, requireCurrentContext: false)
                ?? throw BrowserOriginalMainCondition.Invalid();
            var originalRequest = JsonSerializer.Deserialize<TurnRequest>(browserStaged.RequestJson, JsonOpts)
                ?? throw BrowserOriginalMainCondition.Invalid();
#if DEBUG
            using var diagnosticRequest = _fs.BrowserDiagnosticIdentity(originalRequest.RequestId, null, null, null);
#endif
            await FinalizePlayerTurnAsync(stagedPreparation with
            {
                Request = originalRequest, SnapshotContext = context
            }, action, playerFacingTurn, browserOutcome);
            return true;
        });
#if DEBUG

        }
        catch { _fs.BrowserDiagnosticMark("finalizer-failed"); throw; }
#endif
    }

    private async Task<PlayerTurnPreparation?> StagePlayerTurnAsync(
        string action, string? extraSystemReminder, PendingPlayerActionService.Binding? browserAction)
    {
        var sessionGeneration = await CaptureCurrentSessionGenerationAsync();
        using var browserOriginalScope = browserAction == null ? null : _fs.BeginBrowserOriginalOperation(browserAction);
        // Reserve/refuse before health validation can remove an unrelated request.
        if (browserAction != null) await ClaimBrowserPreparationAsync(browserAction);
        if (!await ValidateCurrentGameStateOrShowErrorsAsync("перед отправкой хода"))
            return null;

        var stagedExplorerRollback = _explorer.ConsumePendingLocalTurnRollbackSnapshot();
        RollbackSnapshot? backedUpFiles = null;
        TurnRequest? request = null;
        ValidatedPendingTurnSnapshotContext? activeSnapshotContext = null;
        PendingPlayerActionService.Staged? browserStaged = null;

        try
        {
            // Create backup of game state files before sending turn (for escape-rollback)
            var backupId = DateTime.UtcNow.Ticks.ToString();
            backedUpFiles = await CreatePreTurnBackup(backupId);
            OverlayExplorerLocalRollbackSnapshot(backedUpFiles, stagedExplorerRollback);

            // Write turn request
            request = new TurnRequest
            {
                SessionId = _gameLoop.SessionId,
                TurnNumber = _gameLoop.TurnNumber + 1,
                PlayerAction = action,
                Timestamp = DateTime.UtcNow.ToString("o"),
                GameMode = _stateManager.Settings.AllowHistoryManipulation ? "debug" : "normal",
                SystemReminder = await BuildTurnSystemReminderAsync(extraSystemReminder)
            };
            if (browserAction != null) request.RequestId = browserAction.ActionId;
            request.ProgressionControl = await _progressionSchedule.BuildControlForNextTurnAsync();
            await AttachPendingDiceAndGachaAsync(request);
            request.AfterlifeSpiritualConflictPreview = await new AfterlifeSpiritualConflictTurnPreviewService(_fs)
                .BuildAsync(request.TurnNumber, request.PreGeneratedDices1d20, _stateManager.CurrentState.CurrentRealm);
            RegisterOrdinaryTurnStagingValidationSnapshotFiles(backedUpFiles);
            var skillScopeAuthority = await EffectMechanicsSnapshot
                .LoadCurrentSkillScopeAuthorityAsync(_fs);
            request.EffectSkillScopeCatalog = skillScopeAuthority
                .CreateGmCatalog()
                .DeepClone()
                .AsObject();
            var canonicalSnapshot = await CreateCanonicalBaselineSnapshotAsync(request, backedUpFiles, OrdinaryPlayerTurnSourceLabel, browserAction);

            // Attach computed characteristics for GM reference
            try
            {
                var computed = await _charService.ComputeAsync();
                var charContext = new Dictionary<string, object>();
                foreach (var (name, stat) in computed.Stats)
                {
                    charContext[name] = new
                    {
                        standard = stat.BaseValue,
                        permanentlyModified = stat.PermanentlyModified,
                        modified = stat.Modified
                    };
                }
                request.ComputedCharacteristics = new
                {
                    playerLevel = computed.PlayerLevel,
                    unspentStatPoints = computed.UnspentStatPoints,
                    stats = charContext
                };
            }
            catch (Exception ex)
            {
                _logger.LogWarning(ex, "Не удалось вычислить характеристики для контекста");
            }

            ClearTransientOutputFiles();
            var requestJson = JsonSerializer.Serialize(request, JsonOpts);
            if (browserAction != null)
            {
                browserStaged = await PublishBrowserStagingAsync(browserAction, requestJson);
                requestJson = browserStaged.RequestJson;
            }
            else
            {
                await using var stagingLease = await _fs.AcquireCanonicalWriteLeaseAsync();
                await _fs.WriteFileAtomicAsync(stagingLease, "input/turn_request.json", requestJson);
                var provisional = new CanonicalBeforeImage(true,
                    await _fs.ReadFileBytesAsync(stagingLease, "input/turn_request.json") ??
                    throw new InvalidDataException("Ordinary provisional request disappeared."));
                requestJson = ProjectOrdinaryWoundOpportunities(stagingLease, requestJson);
                if (!await CoordinatedStateWriteHelper.TryCommitAsync(_fs, stagingLease,
                        new CoordinatedStateWriteHelper.PlannedWrite("input/turn_request.json", null, requestJson, RequireCurrentBaseline: true, ExactPrevious: provisional)))
                    throw new InvalidOperationException("Ordinary request changed before safe opportunity projection.");
                await RequireFinalOrdinaryWoundProjectionAsync(stagingLease, requestJson);
            }

            var projectedRequest = JsonSerializer.Deserialize<TurnRequest>(requestJson, JsonOpts) ??
                throw new InvalidDataException("Final ordinary request is missing.");
            if (projectedRequest.SessionId != request.SessionId || projectedRequest.RequestId != request.RequestId ||
                projectedRequest.TurnNumber != request.TurnNumber || projectedRequest.Timestamp != request.Timestamp ||
                projectedRequest.PlayerAction != request.PlayerAction)
                throw new InvalidDataException("Safe opportunity projection changed ordinary request identity.");
            request = projectedRequest;

            var activeManifest = await LoadPendingTurnSnapshotManifestAsync();
            activeSnapshotContext = await LoadValidatedPendingTurnSnapshotContextAsync(activeManifest);
            if (activeSnapshotContext == null)
                throw new InvalidOperationException("Turn staging failed to create a validated pending snapshot context.");
        }
        catch (SessionReplacedException)
        {
            throw;
        }
        catch (Exception ex) when (ex is not CoordinatedStatePublicationUncertainException)
        {
            if (browserAction != null)
            {
                // Staging never establishes a successful rollback disposition.
                // Preserve the original slot, backup and any competing request;
                // cold preparing/staged classification blocks replay before repair.
                _inGame = false;
                _logger.LogError(ex, "Browser turn staging stopped; original recovery evidence is retained.");
                throw;
            }
            _logger.LogDebug(ex, "Не удалось безопасно поставить ход в очередь; выполняется rollback локальной подготовки.");
            try
            {
                _fs.AllowBrowserOriginalCleanup();
            _fs.DeleteFile("input/turn_request.json");
            }
            catch (CoordinatedStatePublicationUncertainException uncertainty)
            {
                uncertainty.Data["TurnStagingOriginalFailure"] = ex;
                throw;
            }
            catch (Exception cleanupEx)
            {
                _logger.LogDebug(cleanupEx, "Не удалось удалить частичный turn_request.json после ошибки постановки хода.");
            }

            try
            {
                if (backedUpFiles != null)
                {
                    await RestorePreTurnBackup(backedUpFiles);
                    await _explorer.RestoreConsumedLocalTurnRollbackSnapshotAsync(stagedExplorerRollback);
                    CleanupBackup(backedUpFiles);
                }
                else
                {
                    await _explorer.RestoreConsumedLocalTurnRollbackSnapshotAsync(stagedExplorerRollback);
                }
            }
            catch (CoordinatedStatePublicationUncertainException uncertainty)
            {
                uncertainty.Data["TurnStagingOriginalFailure"] = ex;
                throw;
            }
            catch (Exception rollbackEx)
            {
                _logger.LogError(rollbackEx, "Не удалось восстановить локальную подготовку после ошибки постановки хода.");
            }

            try
            {
                await CleanupPendingTurnSnapshotAsync();
            }
            catch (CoordinatedStatePublicationUncertainException uncertainty)
            {
                uncertainty.Data["TurnStagingOriginalFailure"] = ex;
                throw;
            }
            catch (Exception cleanupEx)
            {
                _logger.LogDebug(cleanupEx, "Не удалось полностью очистить частичные артефакты постановки хода.");
            }

            throw;
        }

        if (backedUpFiles == null || request == null || activeSnapshotContext == null)
            throw new InvalidOperationException("Turn staging failed before rollback snapshot and request were created.");

        return new PlayerTurnPreparation(sessionGeneration, backedUpFiles, request, activeSnapshotContext, browserStaged);

    RollbackSnapshot? rollbackSnapshot = null,
    string? sourceLabel = null,
    PendingPlayerActionService.Binding? browserAction = null)
{
    var writeLease = await _fs.AcquireCanonicalWriteLeaseAsync();
    CoordinatedStatePublicationUncertainException? uncertainty = null;
    try { return await CreateCanonicalBaselineSnapshotAsync(writeLease, request, rollbackSnapshot, sourceLabel, browserAction); }
    catch (CoordinatedStatePublicationUncertainException failure) { uncertainty = failure; throw; }
    finally { await CoordinatedStateWriteHelper.ReleaseOwnedLeaseAsync(_fs, writeLease, false, uncertainty); }
}

private async Task<Dictionary<string, string>> CreateCanonicalBaselineSnapshotAsync(
    FileSystemManager.CanonicalWriteLease writeLease,
    TurnRequest request,
    RollbackSnapshot? rollbackSnapshot = null,
    string? sourceLabel = null,
    PendingPlayerActionService.Binding? browserAction = null)
{
    RequireExactEngineSnapshotInventory(writeLease, rollbackSnapshot);
    await DeleteTerminalProtocolFailureRequestAsync(writeLease);
    CleanupPendingTurnSnapshot(writeLease, rollbackSnapshot?.BackupFiles.Values);
    var conflictStateExistedBeforeInitialization = _fs.FileExists(
        writeLease,
        AfterlifeSpiritualConflictState.StatePath);
    var entityProfileStateExistedBeforeInitialization = _fs.FileExists(
        writeLease,
        AfterlifeEntityProfileState.StatePath);
    var chronicleStateExistedBeforeInitialization = _fs.FileExists(
        writeLease,
        AfterlifeChronicleState.StatePath);
    var globalFlagStateExistedBeforeInitialization = _fs.FileExists(
        writeLease,
        AfterlifeGlobalFlagState.StatePath);
    await EnsureAfterlifeSpiritualConflictStateInitializedForSnapshotAsync(writeLease);
    await EnsureAfterlifeEntityProfileStateInitializedForSnapshotAsync(writeLease);
    await EnsureAfterlifeChronicleStateInitializedForSnapshotAsync(writeLease);
    await EnsureAfterlifeGlobalFlagStateInitializedForSnapshotAsync(writeLease);
    await RegisterAfterlifeSpiritualConflictRollbackBackupIfInitializedAsync(
        writeLease,
        request,
        rollbackSnapshot,
        conflictStateExistedBeforeInitialization);
    await RegisterAfterlifeEntityProfileRollbackBackupIfInitializedAsync(
        writeLease,
        request,
        rollbackSnapshot,
        entityProfileStateExistedBeforeInitialization);
    await RegisterAfterlifeChronicleRollbackBackupIfInitializedAsync(
        writeLease,
        request,
        rollbackSnapshot,
        chronicleStateExistedBeforeInitialization);
    await RegisterAfterlifeGlobalFlagRollbackBackupIfInitializedAsync(
        writeLease,
        request,
        rollbackSnapshot,
        globalFlagStateExistedBeforeInitialization);

    RequireExactEngineSnapshotInventory(writeLease, rollbackSnapshot);
    var files = new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase);
    var snapshotHashes = new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase);
    var clientOwnedValidationHashes = await CaptureClientOwnedValidationHashesAsync(writeLease);
    var rollbackBaselineFiles = rollbackSnapshot?.BaselineFiles is { Count: > 0 }
        ? new HashSet<string>(rollbackSnapshot.BaselineFiles, StringComparer.OrdinalIgnoreCase)
        : new HashSet<string>(EnumerateRollbackTrackedFiles(writeLease), StringComparer.OrdinalIgnoreCase);

    foreach (var file in GuardianPolicySnapshotRequestFiles)
    {
        if (_fs.FileExists(writeLease, file))
            rollbackBaselineFiles.Add(file);
        else
            rollbackBaselineFiles.Remove(file);
    }
    if (_fs.FileExists(writeLease, SourceOfLightCapstoneState.PendingRequestPath))
        rollbackBaselineFiles.Add(SourceOfLightCapstoneState.PendingRequestPath);
    else
        rollbackBaselineFiles.Remove(SourceOfLightCapstoneState.PendingRequestPath);
    if (_fs.FileExists(writeLease, SarefMainStoryState.PendingWingsInfiltrationPath))
        rollbackBaselineFiles.Add(SarefMainStoryState.PendingWingsInfiltrationPath);
    else
        rollbackBaselineFiles.Remove(SarefMainStoryState.PendingWingsInfiltrationPath);
    if (_fs.FileExists(writeLease, AfterlifeSpiritualConflictState.StatePath))
        rollbackBaselineFiles.Add(AfterlifeSpiritualConflictState.StatePath);
    if (_fs.FileExists(writeLease, AfterlifeEntityProfileState.StatePath))
        rollbackBaselineFiles.Add(AfterlifeEntityProfileState.StatePath);
    if (_fs.FileExists(writeLease, AfterlifeChronicleState.StatePath))
        rollbackBaselineFiles.Add(AfterlifeChronicleState.StatePath);
    if (_fs.FileExists(writeLease, AfterlifeGlobalFlagState.StatePath))
        rollbackBaselineFiles.Add(AfterlifeGlobalFlagState.StatePath);
    if (_fs.FileExists(writeLease, SarefMainStoryState.StatePath))
        rollbackBaselineFiles.Add(SarefMainStoryState.StatePath);

    var snapshotFiles = new HashSet<string>(rollbackBaselineFiles, StringComparer.OrdinalIgnoreCase);
    if (rollbackSnapshot?.ValidationSnapshotFiles is { Count: > 0 })
    {
        foreach (var file in rollbackSnapshot.ValidationSnapshotFiles)
        {
            if (!string.IsNullOrWhiteSpace(file))
                snapshotFiles.Add(file);
        }
    }
    snapshotFiles.UnionWith(PendingTurnSnapshotPathPresenceV1.LogicalPaths);

    foreach (var file in snapshotFiles.OrderBy(path => path, StringComparer.OrdinalIgnoreCase))
    {
        await SnapshotFileOrRollbackBackupIfPresentAsync(
            writeLease,
            file,
            rollbackSnapshot,
            files,
            snapshotHashes);
    }
    var originalPathPresenceV1 =
        PendingTurnSnapshotPathPresenceV1.Create(files, snapshotHashes);

    var manifest = new PendingTurnSnapshotManifest
    {
        SessionId = request.SessionId,
        RequestId = request.RequestId,
        TurnNumber = request.TurnNumber,
        RequestTimestamp = request.Timestamp,
        PlayerAction = request.PlayerAction,
        PreGeneratedDices1d20 = request.PreGeneratedDices1d20,
        GachaBaseResult = request.GachaBaseResult == null
            ? null
            : JsonSerializer.SerializeToNode(request.GachaBaseResult, JsonOpts) as JsonObject,
        ProgressionControl = request.ProgressionControl,
        Files = files,
        SnapshotFileHashes = snapshotHashes,
        OriginalPathPresenceV1 = originalPathPresenceV1,
        ClientOwnedValidationHashes = clientOwnedValidationHashes,
        RollbackBackups = rollbackSnapshot != null
            ? new Dictionary<string, string>(rollbackSnapshot.BackupFiles, StringComparer.OrdinalIgnoreCase)
            : new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase),
        RollbackBaselineFiles = rollbackBaselineFiles
            .OrderBy(path => path, StringComparer.OrdinalIgnoreCase)
            .ToList(),
        SourceLabel = sourceLabel,
        BrowserActionId = browserAction?.ActionId,
        BrowserSessionGeneration = browserAction?.Generation,
        BrowserOriginalMainCondition = browserAction == null ? null : _fs.CaptureBrowserOriginalCondition(writeLease, browserAction.Generation)
    };
    manifest.ManifestPayloadHash = ComputePendingTurnManifestPayloadHash(manifest);
    var authorityJson = PendingTurnSnapshotAuthority.CreateDetachedAuthorityJson(
        manifest,
        SnapshotHashJsonOpts,
        static snapshotManifest => snapshotManifest.ManifestPayloadHash,
        static (snapshotManifest, hash) => snapshotManifest.ManifestPayloadHash = hash,
        static snapshotManifest => snapshotManifest.SessionId,
        static snapshotManifest => snapshotManifest.RequestId,
        static snapshotManifest => snapshotManifest.TurnNumber,
        static snapshotManifest => snapshotManifest.Files,
        static snapshotManifest => snapshotManifest.SnapshotFileHashes,
        static snapshotManifest => snapshotManifest.ClientOwnedValidationHashes,
        static snapshotManifest => snapshotManifest.RollbackBaselineFiles,
        static snapshotManifest => snapshotManifest.SourceLabel,
        static snapshotManifest => snapshotManifest.RollbackBackups,
        relativePath => ReadRelativeFileBytesFromWorkspace(writeLease, relativePath));

    try
    {
        await _fs.WriteFileAtomicAsync(
            writeLease,
            PendingTurnSnapshotManifestPath,
            JsonSerializer.Serialize(manifest, JsonOpts));
        await _fs.WriteFileAtomicAsync(
            writeLease,
            PendingTurnSnapshotAuthority.AuthorityPath,
            authorityJson);
    }
    catch (Exception failure) when (failure is not CoordinatedStatePublicationUncertainException)
    {
        try
        {
            if (_fs.FileExists(writeLease, PendingTurnSnapshotManifestPath))
                _fs.DeleteFile(writeLease, PendingTurnSnapshotManifestPath);
            if (_fs.FileExists(writeLease, PendingTurnSnapshotAuthority.AuthorityPath))
                _fs.DeleteFile(writeLease, PendingTurnSnapshotAuthority.AuthorityPath);
        }
        catch (CoordinatedStatePublicationUncertainException uncertainty)
        {
            uncertainty.Data["PreparationPublicationFailure"] = failure;
            throw;
        }
        throw;
    }

    return files;
}

private async Task RegisterAfterlifeSpiritualConflictRollbackBackupIfInitializedAsync(
    FileSystemManager.CanonicalWriteLease writeLease,
    TurnRequest request,
    RollbackSnapshot? rollbackSnapshot,

        woundRequiredResubmissionPaths,
        effectRepairPackets,
        isBoundedPendingResolutionResubmission);
    ThrowIfValidationRepairDispatchSessionReplaced(dispatch);
    if (dispatch.MetadataDiagnosticOnly)
        return await FailClosedDiagnosticOnlyValidationRepairAsync(
            source,
            errors,
            attempt,
            rollbackSnapshot,
            repairSessionGeneration);

    if (dispatch.WorkerApplyAccepted && !dispatch.ReadySignalCreated)
    {
        await AppendWorkerAcceptedValidationRepairTrajectoryAsync(source, errors, attempt, dispatch);
        return true;
    }

    using var agentConsoleRepairInputBlock = BeginAgentConsoleInputBlockFromCurrentSnapshot(
        PlayerSafeInputBlockedText);

    while (true)
    {
        using var cts = new CancellationTokenSource();
        var startTime = DateTime.UtcNow;
        var harnessTerminalErrorPublished = false;

        var waitTask = Task.Run(async () =>
        {
            while (!cts.Token.IsCancellationRequested)
            {
                await EnsureRepairSessionCurrentAsync(repairSessionGeneration);
                if (_fs.FileExists(ValidationRepairReadyPath))
                    return true;
                if (_fs.FileExists(ValidationRepairArtifactStallReportPath))
                {
                    var pendingSnapshot = await ResolveActivePendingTurnSnapshotContextAsync();
                    if (pendingSnapshot is { Status: PendingTurnSnapshotResolutionStatus.Usable, Context: not null } &&
                        await TryPromoteValidationRepairArtifactStallToTerminalErrorAsync(
                            pendingSnapshot.Context,
                            repairSessionGeneration))
                    {
                        harnessTerminalErrorPublished = true;
                        return false;
                    }
                }

                await Task.Delay(500, cts.Token);
            }
            return false;
        }, cts.Token);

        var result = await AnsiConsole.Status()
            .Spinner(Spinner.Known.Dots12)
            .SpinnerStyle(Style.Parse("yellow"))
            .StartAsync(rollbackAvailable
                ? "[yellow]⏳ Мир ещё не готов продолжить ход... (Escape = вернуться к состоянию до хода)[/]"
                : "[yellow]⏳ Мир ещё не готов продолжить ход... (Escape = прекратить ожидание)[/]", async ctx =>
            {
                while (!waitTask.IsCompleted && !cts.IsCancellationRequested)
                {
                    var elapsed = (int)(DateTime.UtcNow - startTime).TotalSeconds;
                    ctx.Status(rollbackAvailable
                        ? $"[yellow]⏳ Мир ещё не готов продолжить ход... ({elapsed}с) (Escape = вернуться)[/]"
                        : $"[yellow]⏳ Мир ещё не готов продолжить ход... ({elapsed}с) (Escape = выйти)[/]");

                    if (_inputSource.KeyAvailable)
                    {
                        var key = _inputSource.ReadKey(intercept: true);
                        if (key.Key == ConsoleKey.Escape)
                        {
                            if (_mortalJointRepairCheckpoint is not null) _mortalJointRepairTerminalReason = "cancelled";
                            cts.Cancel();
                        }
                    }

                    await Task.Delay(1000);
                }

                try { return await waitTask; }
                catch (OperationCanceledException) { return false; }
            });

        if (cts.IsCancellationRequested)
        {
            if (rollbackAvailable)
            {
                AnsiConsole.MarkupLine("[yellow]⏹ Изменения мира не были приняты; состояние до хода будет восстановлено.[/]");
            }
            else
            {
                AnsiConsole.MarkupLine("[yellow]⏹ Продолжение хода остановлено; дальнейшие изменения не принимаются.[/]");
            }

            await RunBestEffortFailClosedBookkeepingAsync(
                "delete the transient report after validation-repair cancellation",
                async () =>
                {
                    if (!await _progressionSchedule.DeleteTransientReportIfCurrentSessionAsync(
                            repairSessionGeneration))
                    {
                        throw new GmWorkerSessionReplacedException(
                            "The validation-repair cycle belongs to a game session that is no longer current.");
                    }
                });
            await RunBestEffortFailClosedBookkeepingAsync(
                "clean validation-repair control files after cancellation",
                () => DeleteValidationRepairFilesForSessionAsync(repairSessionGeneration));
            return false;
        }

        if (harnessTerminalErrorPublished)
        {
            AnsiConsole.MarkupLine("[yellow]⏹ Мир не смог завершить этот ход; продолжение остановлено.[/]");
            return false;
        }

        if (!result)
            continue;

        var readyJson = await ReadValidationRepairFileForSessionAsync(
            ValidationRepairReadyPath,
            repairSessionGeneration);
        var ready = ReadValidationRepairReady(readyJson);
        var pendingSnapshot = await ResolveActivePendingTurnSnapshotContextAsync();
        if (ready == null)
        {
            _logger.LogWarning("Отклонён validation_repair_ready: файл не читается как валидный JSON");
            var rejectedReadyRepair = await ReportRejectedRepairReadyAsync(
                source,
                errors,
                attempt,
                "invalid_repair_ready_json",
                "Клиент отклонил validation_repair_ready.json: файл не читается как валидный JSON.",
                "Valid JSON object with matching sessionId/requestId/turnNumber for the active repair cycle",
                string.IsNullOrWhiteSpace(readyJson) ? "missing or empty file" : TruncateDiagnosticValue(readyJson),
                BuildInvalidRepairReadyRepairHint(pendingSnapshot),
                repairSessionGeneration);
            ThrowIfValidationRepairDispatchSessionReplaced(rejectedReadyRepair.Dispatch);
            if (rejectedReadyRepair.Dispatch.MetadataDiagnosticOnly)
                return await FailClosedDiagnosticOnlyValidationRepairAsync(
                    source,
                    rejectedReadyRepair.ReportErrors,
                    attempt,
                    rollbackSnapshot,
                    repairSessionGeneration);

            if (rejectedReadyRepair.Dispatch.WorkerApplyAccepted)
            {
                if (!rejectedReadyRepair.Dispatch.ReadySignalCreated)
                {
                    await AppendWorkerAcceptedValidationRepairTrajectoryAsync(
                        source,
                        rejectedReadyRepair.ReportErrors,
                        attempt,
                        rejectedReadyRepair.Dispatch);
                    return true;
                }

                continue;
            }

            await DeleteValidationRepairReadyForSessionAsync(repairSessionGeneration);
            AnsiConsole.MarkupLine("[yellow]⚠ Мир ещё не готов продолжить ход. Ожидание продолжается.[/]");
            await Task.Delay(500);
            continue;
        }

        if (!IsMatchingRepairReady(ready, pendingSnapshot.Context))
        {
            _logger.LogWarning(
                "Отклонён validation_repair_ready(session={Session}, request={Request}, turn={Turn}) — ожидается (session={ExpectedSession}, request={ExpectedRequest}, turn={ExpectedTurn})",
                ready.SessionId,
                ready.RequestId,
                ready.TurnNumber,
                pendingSnapshot.Context?.SessionId,
                pendingSnapshot.Context?.RequestId,
                pendingSnapshot.Context?.TurnNumber);

            var rejectedReadyRepair = await ReportRejectedRepairReadyAsync(
                source,
                errors,
                attempt,
                "mismatched_repair_ready_context",
                "Клиент отклонил validation_repair_ready.json: metadata не совпадает с активным repair cycle.",
                BuildExpectedRepairContext(pendingSnapshot),
                BuildActualRepairContext(ready, pendingSnapshot),
                BuildMismatchedRepairReadyRepairHint(pendingSnapshot),
                repairSessionGeneration);
            ThrowIfValidationRepairDispatchSessionReplaced(rejectedReadyRepair.Dispatch);
            if (rejectedReadyRepair.Dispatch.MetadataDiagnosticOnly)
                return await FailClosedDiagnosticOnlyValidationRepairAsync(
                    source,
                    rejectedReadyRepair.ReportErrors,
                    attempt,
                    rollbackSnapshot,
                    repairSessionGeneration);

            if (rejectedReadyRepair.Dispatch.WorkerApplyAccepted)
            {
                if (!rejectedReadyRepair.Dispatch.ReadySignalCreated)
                {
                    await AppendWorkerAcceptedValidationRepairTrajectoryAsync(
                        source,
                        rejectedReadyRepair.ReportErrors,
                        attempt,
                        rejectedReadyRepair.Dispatch);
                    return true;
                }

                continue;
            }

            await DeleteValidationRepairReadyForSessionAsync(repairSessionGeneration);
            AnsiConsole.MarkupLine("[yellow]⚠ Мир ещё не готов продолжить ход. Ожидание продолжается.[/]");
            await Task.Delay(500);
            continue;
        }

        await AppendAcceptedValidationRepairTrajectoryAsync(
            source,
            errors,
            attempt,
            ready,
            pendingSnapshot,
            repairSessionGeneration);
        await DeleteValidationRepairReadyForSessionAsync(repairSessionGeneration);
        return true;
    }
}

private async Task AppendAcceptedValidationRepairTrajectoryAsync(
    string source,
    List<ValidationIssue> errors,
    int attempt,
    ValidationRepairReady ready,
    PendingTurnSnapshotResolution pendingSnapshot,
    string expectedSessionGeneration,
    string acceptanceScope = "correlated_repair_ready",
    string terminalKind = "validation_repair_ready",
    string? signalPath = ValidationRepairReadyPath,
    string dispatchStatus = "client_observed_terminal")
{
    const string ledgerPath = "game_state/control/gm_trajectory_ledger.jsonl";

    try
    {
        var context = pendingSnapshot.Context;
        var realmResolution = BuildValidationRepairTrajectoryRealmResolution(context);
        var repairPacketRefs = await BuildValidationRepairTrajectoryRepairPacketRefsAsync(errors);
        var record = new
        {
            recordId = "gmtraj_" + Guid.NewGuid().ToString("N"),
            kind = "repair",
            sessionId = ready.SessionId,
            turnId = ready.RequestId,
            requestId = ready.RequestId,
            turnNumber = ready.TurnNumber,
            realm = realmResolution.Realm,
            realmResolution,
            mode = "validation_repair",
            actionSummary = BuildValidationRepairTrajectoryActionSummary(context),
            contextPackPath = "game_state/control/gm_context_pack",
            templateVersions = new
            {
                turnOutput = "v1",
                validationRepair = "v1",
                progressionReport = "v1",
                actorReasoning = "v1",
                tempoAdvantage = "v1"
            },
            outputFiles = Array.Empty<string>(),
            dispatch = new
            {
                attempts = 0,
                busyRetries = 0,
                timeout = false,
                status = dispatchStatus
            },
            validation = new
            {
                status = "accepted",
                source,
                acceptanceScope,
                fullCanonicalStateAccepted = false,
                issueKinds = BuildValidationRepairTrajectoryIssueKinds(errors),
                repairPacketRefs
            },
            repair = new
            {
                attempts = attempt,
                status = "accepted"
            },
            workerEvents = Array.Empty<object>(),
            rollbackEvents = Array.Empty<object>(),
            terminal = new
            {
                kind = terminalKind,
                signalPath
            },
            durationSeconds = (double?)null,
            rubric = new
            {
                validTurn = true,
                playerFacingOutputPresent = _fs.FileExists("output/narrative_response.json"),
                implementationSourceRead = false,
                rawWrongRealmWrite = false,
                manualReasoningNeeded = false,
                missingHarnessTool = (string?)null
            },
            createdAt = DateTime.UtcNow.ToString("o"),
            observedBy = "client"
        };

        var json = JsonSerializer.Serialize(record, new JsonSerializerOptions(JsonOpts)
        {
            WriteIndented = false
        });
        if (!await _fs.AppendFileAtomicIfCurrentSessionAsync(
                ledgerPath,
                json + Environment.NewLine,
                expectedSessionGeneration))
        {
            throw new GmWorkerSessionReplacedException(
                "The accepted validation-repair trajectory belongs to a game session that is no longer current.");
        }
    }
    catch (SessionReplacedException)
    {
        throw;
    }
    catch (Exception ex) when (ex is not CoordinatedStatePublicationUncertainException)
    {
        _logger.LogWarning(
            ex,
            "Failed to append accepted validation repair trajectory after {Source}. Gameplay continues without ledger entry.",
            source);
    }
}

private async Task DeleteValidationRepairReadyForSessionAsync(string expectedSessionGeneration)
{
    var writeLease = await _fs.AcquireCanonicalWriteLeaseAsync();
    CoordinatedStatePublicationUncertainException? uncertainty = null;
    try
    {
        ThrowIfRepairSessionReplaced(writeLease, expectedSessionGeneration);
        _fs.DeleteFile(writeLease, ValidationRepairReadyPath);
    }
    catch (CoordinatedStatePublicationUncertainException failure)
    {
        uncertainty = failure;
        throw;
    }
    finally
    {
        await CoordinatedStateWriteHelper.ReleaseOwnedLeaseAsync(_fs, writeLease, false, uncertainty);
    }

}

private async Task WriteValidationRepairFileForSessionAsync(
    string relativePath,
    string content,
    string expectedSessionGeneration)
{
    var writeLease = await _fs.AcquireCanonicalWriteLeaseAsync();
    CoordinatedStatePublicationUncertainException? uncertainty = null;
    try
    {
        ThrowIfRepairSessionReplaced(writeLease, expectedSessionGeneration);
        await _fs.WriteFileAtomicAsync(writeLease, relativePath, content);
    }
    catch (CoordinatedStatePublicationUncertainException failure) { uncertainty = failure; throw; }
    finally { await CoordinatedStateWriteHelper.ReleaseOwnedLeaseAsync(_fs, writeLease, false, uncertainty); }
}

private async Task<string?> ReadValidationRepairFileForSessionAsync(
    string relativePath,
    string expectedSessionGeneration)
{
    await using var writeLease = await _fs.AcquireCanonicalWriteLeaseAsync();
    ThrowIfRepairSessionReplaced(writeLease, expectedSessionGeneration);
    return await _fs.ReadFileAsync(writeLease, relativePath);
}

private void ThrowIfRepairSessionReplaced(
    FileSystemManager.CanonicalWriteLease writeLease,
    string expectedSessionGeneration)
{
    if (!_fs.IsCurrentSessionGeneration(writeLease, expectedSessionGeneration))
    {
        throw new GmWorkerSessionReplacedException(
            "The validation-repair cycle belongs to a game session that is no longer current.");
    }
}

